using System.IO;
using System.Diagnostics;
using System.Windows;
using System.Windows.Controls;
namespace Captovix;
public partial class MainWindow
{
    private void ReleaseRecovery_Click(object sender,RoutedEventArgs e){if(_busy||!FlushEdits())return;var panel=new StackPanel{Margin=new(18)};var window=new Window{Owner=this,Title="Captovix · Cập nhật & khôi phục",Width=620,Height=500,WindowStartupLocation=WindowStartupLocation.CenterOwner,Content=panel};panel.Children.Add(new TextBlock{Text="Bản sao lưu trước cập nhật",FontSize=21,FontWeight=FontWeights.SemiBold});panel.Children.Add(new TextBlock{Text="Giữ ảnh/video nguồn. Phục hồi thiết lập/chỉnh sửa từ bản đã chọn sau khi đóng app; tạo bản an toàn trước khi thay dữ liệu. License mã hóa chỉ dùng trên cùng máy/tài khoản Windows.",TextWrapping=TextWrapping.Wrap,Margin=new(0,8,0,12)});var list=new ListBox{Height=240};panel.Children.Add(list);string folder=Path.Combine(App.DataRoot,"Backups");if(Directory.Exists(folder))foreach(var file in Directory.GetFiles(folder,"*.zip").OrderByDescending(File.GetLastWriteTimeUtc).Take(50))list.Items.Add(new ListBoxItem{Content=Path.GetFileName(file)+" · "+StorageMaintenance.Size(new FileInfo(file).Length),Tag=file});var message=new TextBlock{TextWrapping=TextWrapping.Wrap};panel.Children.Add(message);var actions=new DockPanel();var close=new Button{Content="Đóng"};close.Click+=(_,_)=>window.Close();actions.Children.Add(close);var restore=new Button{Content="Kiểm tra & khôi phục",HorizontalAlignment=HorizontalAlignment.Right};actions.Children.Add(restore);panel.Children.Add(actions);
        restore.Click+=async(_,_)=>{if(list.SelectedItem is not ListBoxItem{Tag:string path}){message.Text="Chọn một bản sao lưu.";return;}restore.IsEnabled=false;try{var info=await Task.Run(()=>UpdateBackup.Inspect(path));if(AppDialog.Show(window,$"Khôi phục bản {info.From} ngày {info.Created.ToLocalTime():dd/MM/yyyy HH:mm}, {info.Files.Count}tệp?\nDữ liệu chỉnh sửa hiện tại sẽ được sao lưu riêng trước khi thay. Ảnh/video gốc giữ nguyên.","Khôi phục dữ liệu",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;if(!FlushEdits())return;_store.Save();_store.SaveSettings(Settings());var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false};start.ArgumentList.Add("--restore-backup");start.ArgumentList.Add(path);start.ArgumentList.Add(Environment.ProcessId.ToString());Process.Start(start);window.Close();RequestExit();}catch(Exception ex){message.Text=ex.Message;}finally{restore.IsEnabled=true;}};
        window.ShowDialog();
    }
}
